function bodyOf(value) {
  if (typeof value === 'string') return value;
  if (!value || typeof value !== 'object') return '';
  if (typeof value.body === 'string') return value.body;
  if (typeof value.data === 'string') return value.data;
  return '';
}
function normalizeHtml(value) {
  return String(value || '')
    .replace(/\\u002F/gi, '/')
    .replace(/\\u0026/gi, '&')
    .replace(/\\\//g, '/')
    .replace(/&amp;/gi, '&');
}
const response = $input.first().json || {};
const html = normalizeHtml(bodyOf(response));
if (!html || html.length < 100) throw new Error('Spotify public artist page returned an empty response');
const found = new Map();
function add(id, source) {
  id = String(id || '').trim();
  if (!/^[A-Za-z0-9]{10,40}$/.test(id)) return;
  if (!found.has(id)) found.set(id, {
    id,
    release_url: `https://open.spotify.com/embed/album/${id}`,
    listen_url: `https://open.spotify.com/album/${id}`,
    source: source || 'spotify-public-artist-page'
  });
}
for (const regex of [
  /open\.spotify\.com\/(?:intl-[a-z]{2}\/)?album\/([A-Za-z0-9]+)/gi,
  /spotify:album:([A-Za-z0-9]+)/gi,
  /["']uri["']\s*:\s*["']spotify:album:([A-Za-z0-9]+)/gi,
  /href=["'][^"']*\/album\/([A-Za-z0-9]+)/gi
]) {
  let match;
  while ((match = regex.exec(html)) !== null) add(match[1]);
}
// Baseline fallbacks ensure existing releases are never mistaken for a new release
// when Spotify temporarily renders a reduced public page.
add('5dAAKIVnr96ILc9gxPnRzt', 'baseline-fallback'); // Echoes Of The Modern Mind
add('3sCeTZ7ZAk1LRUemrLQjVy', 'baseline-fallback'); // From The Ashes EP
const releases = Array.from(found.values()).slice(0, 50);
if (!releases.length) throw new Error('No Virya Spotify release IDs found on the public artist page');
return releases.map(json => ({ json }));

function clean(value) { return String(value ?? '').trim(); }
function bodyOf(value) {
  if (typeof value === 'string') return value;
  if (!value || typeof value !== 'object') return '';
  if (typeof value.body === 'string') return value.body;
  if (typeof value.data === 'string') return value.data;
  return '';
}
function decode(value) {
  return clean(value)
    .replace(/\\u002F/gi, '/')
    .replace(/\\u0026/gi, '&')
    .replace(/\\u003C/gi, '<')
    .replace(/\\u003E/gi, '>')
    .replace(/\\\//g, '/')
    .replace(/\\"/g, '"')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}
function stripTags(value) { return decode(value).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); }
function firstMatch(source, patterns) {
  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (match && clean(match[1])) return stripTags(match[1]);
  }
  return '';
}
function releaseFromPage(input, response, index) {
  const raw = decode(bodyOf(response));
  if (!raw || raw.length < 100) return null;
  let title = firstMatch(raw, [
    /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
    /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i,
    /<title[^>]*>([\s\S]*?)<\/title>/i
  ]);
  title = title
    .replace(/\s*[-–|]\s*Spotify.*$/i, '')
    .replace(/\s*-\s*(?:Album|Single|EP) by Virya.*$/i, '')
    .trim();
  const date = firstMatch(raw, [
    /["']release_date["']\s*:\s*["'](\d{4}-\d{2}-\d{2})["']/i,
    /["']releaseDate["']\s*:\s*["'](\d{4}-\d{2}-\d{2})["']/i,
    /["']datePublished["']\s*:\s*["'](\d{4}-\d{2}-\d{2})["']/i,
    /["']releaseDate["']\s*:\s*\{[^}]*["']isoString["']\s*:\s*["'](\d{4}-\d{2}-\d{2})/i
  ]);
  const image = firstMatch(raw, [
    /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i,
    /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i
  ]);
  const trackIds = new Set();
  for (const regex of [
    /spotify:track:([A-Za-z0-9]+)/gi,
    /open\.spotify\.com\/(?:intl-[a-z]{2}\/)?track\/([A-Za-z0-9]+)/gi
  ]) {
    let match;
    while ((match = regex.exec(raw)) !== null) trackIds.add(match[1]);
  }
  const totalMatch = raw.match(/["']total_tracks["']\s*:\s*(\d{1,4})/i);
  const totalTracks = totalMatch ? Number(totalMatch[1]) : trackIds.size;
  const albumTypeMatch = raw.match(/["']album_type["']\s*:\s*["'](album|single|ep)["']/i);
  const rawType = clean(albumTypeMatch?.[1]).toLowerCase();
  const releaseType = rawType === 'single' || totalTracks === 1
    ? 'single'
    : (rawType === 'ep' || (totalTracks > 1 && totalTracks <= 6) ? 'ep' : 'album');
  if (!title || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;
  return {
    id: clean(input.id),
    title,
    release_date: date,
    release_type: releaseType,
    listen_url: clean(input.listen_url) || `https://open.spotify.com/album/${clean(input.id)}`,
    cover_url: /^https:\/\//i.test(image) ? image : null,
    total_tracks: totalTracks || null,
    artist_name: 'Virya',
    source: 'spotify-public-page',
    site_url: 'https://virya.music/pl/',
    discovery_order: index
  };
}

const releaseInputs = $('Spotify — Find release IDs').all().map(item => item.json || {});
const responses = $input.all().map(item => item.json || {});
const manual = String($execution.mode || '').toLowerCase() === 'manual';

const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Warsaw', year: 'numeric', month: '2-digit', day: '2-digit'
}).formatToParts(now).reduce((acc, part) => { acc[part.type] = part.value; return acc; }, {});
const today = `${parts.year}-${parts.month}-${parts.day}`;
const cutoff = new Date(`${today}T00:00:00Z`);
cutoff.setUTCDate(cutoff.getUTCDate() - 14);
const cutoffDate = cutoff.toISOString().slice(0, 10);

const normalized = [];
const parsedIds = new Set();
for (let index = 0; index < responses.length; index += 1) {
  const input = releaseInputs[index] || {};
  const release = releaseFromPage(input, responses[index], index);
  if (!release?.id || parsedIds.has(release.id) || release.release_date > today) continue;
  parsedIds.add(release.id);
  normalized.push(release);
}
normalized.sort((a, b) => b.release_date.localeCompare(a.release_date) || a.discovery_order - b.discovery_order || a.id.localeCompare(b.id));
normalized.forEach(release => { delete release.discovery_order; });

if (manual) {
  const latest = normalized[0];
  return latest
    ? [{ json: { enqueue: false, status: 'manual_preview', release: latest, discovered_release_ids: releaseInputs.length } }]
    : [{ json: { enqueue: false, status: 'release_metadata_unavailable', discovered_release_ids: releaseInputs.length } }];
}

const recent = normalized.filter(release => release.release_date >= cutoffDate);
if (!recent.length) return [{ json: {
  enqueue: false,
  status: 'no_recent_release',
  checked_at: now.toISOString(),
  discovered_release_ids: releaseInputs.length,
  parsed_release_count: normalized.length
} }];

// CrowdRelay owns durable deduplication via Idempotency-Key spotify:<release_id>.
// n8n intentionally keeps no seen-release business state.
return recent.map(release => ({ json: { enqueue: true, status: 'recent_release', release } }));
